<script setup lang="ts">
import { t as uiText } from '@/locales'

import {computed,ref,watch} from 'vue'
import {ElMessage} from 'element-plus'
import {supplierColors,saveSupplierColors,type SupplierColor,type SupplierColorReference} from '@/api/modules/supplierRanges'
import {newRequestId} from '@/api/modules/partner'
import {getDocuments,uploadDocument,type AttachmentVO} from '@/api/modules/attachment'
import {MAX_UPLOAD_FILE_SIZE_BYTES,formatFileSize} from '@/utils/file'
import {useUserStore} from '@/stores/user'
import {partnerError} from '@/utils/partnerError'
import PartnerPhoto from '@/views/partner/PartnerPhoto.vue'
const props=defineProps<{supplierCode:string;canWrite:boolean}>()
const rows=ref<SupplierColor[]>([]),total=ref(0),page=ref(1),keyword=ref(''),includeHistory=ref(false),common=ref<string[]>([]),allowed=ref(false),busy=ref(false),error=ref('')
const colorEditor=ref<Partial<SupplierColor>>(),reason=ref(''),imageTarget=ref<Partial<SupplierColor>>(),imageOptions=ref<AttachmentVO[]>([]),imageSelected=ref(new Map<number,SupplierColorReference>()),imageKeyword=ref(''),imagePage=ref(1),imageTotal=ref(0),imageBusy=ref(false),imageError=ref('')
const user=useUserStore(),canEdit=computed(()=>props.canWrite&&allowed.value),canUpload=computed(()=>canEdit.value&&user.hasPermission('documents:write'))
let sequence=0,imageGeneration=0
async function load(){const current=++sequence;busy.value=true;error.value='';try{const data=await supplierColors(props.supplierCode,{page:page.value,size:20,keyword:keyword.value,...(!includeHistory.value?{scope:'general'}:{})});if(current===sequence){rows.value=data.content;total.value=data.totalElements;allowed.value=data.canWrite;common.value=data.commonColors||[]}}catch(e){if(current===sequence)error.value=partnerError(e)}finally{if(current===sequence)busy.value=false}}
watch(()=>props.supplierCode,()=>{page.value=1;colorEditor.value=undefined;closeColorImages();void load()},{immediate:true})
async function addCommon(){if(!canEdit.value||busy.value)return;busy.value=true;error.value='';try{await saveSupplierColors(props.supplierCode,{requestId:newRequestId(),reason:'初始化常用颜色候选；不代表产品全部可供，不建立公司标准色码',reuseExisting:true,items:common.value.map(name=>({name,notes:'常用颜色候选；实际可供颜色请在产品中选择'}))});ElMessage.success(uiText('常用颜色已准备好；已有记录保留'));await load()}catch(e){error.value=partnerError(e)}finally{busy.value=false}}
function editColor(color?:SupplierColor){colorEditor.value=color?JSON.parse(JSON.stringify(color)):{id:0,version:0,name:'',supplierColorCode:'',styleKey:'',configKey:'',status:'active',refs:[],notes:''};reason.value=color?'维护供应商颜色':'新增供应商颜色'}
async function saveColor(){if(!canEdit.value||busy.value||!colorEditor.value?.name?.trim())return;busy.value=true;error.value='';try{await saveSupplierColors(props.supplierCode,{requestId:newRequestId(),reason:reason.value||'维护供应商颜色',items:[colorEditor.value]});colorEditor.value=undefined;await load();ElMessage.success(uiText('颜色已保存'))}catch(e){error.value=partnerError(e)}finally{busy.value=false}}
async function setStatus(color:SupplierColor){if(!canEdit.value||busy.value)return;busy.value=true;error.value='';try{await saveSupplierColors(props.supplierCode,{requestId:newRequestId(),reason:color.status==='active'?'停用供应商颜色；保留历史引用':'启用供应商颜色',items:[{...color,status:color.status==='active'?'inactive':'active'}]});await load()}catch(e){error.value=partnerError(e)}finally{busy.value=false}}
const imageReference=(file:AttachmentVO):SupplierColorReference=>({id:file.attachmentId,name:file.originalFileName,version:file.versionNo,type:file.contentType||'',contentType:file.contentType||'',size:file.fileSize})
async function loadColorImages(){const current=++imageGeneration;imageBusy.value=true;imageError.value='';try{const data=await getDocuments({fileCategory:'sample_image',keyword:imageKeyword.value.trim(),page:imagePage.value,size:12,status:'all'});if(current===imageGeneration){imageOptions.value=data.content.map(row=>row.latestVersion).filter(file=>file.contentType?.startsWith('image/'));imageTotal.value=data.totalElements}}catch(e){if(current===imageGeneration)imageError.value=partnerError(e)}finally{if(current===imageGeneration)imageBusy.value=false}}
function chooseColorImages(target:Partial<SupplierColor>){imageTarget.value=target;imageSelected.value=new Map((target.refs||[]).map(ref=>[ref.id,{...ref}]));imageKeyword.value='';imagePage.value=1;void loadColorImages()}
function toggleColorImage(file:AttachmentVO,checked:boolean){const selected=new Map(imageSelected.value);if(checked)selected.set(file.attachmentId,imageReference(file));else selected.delete(file.attachmentId);imageSelected.value=selected}
function applyColorImages(){if(imageTarget.value)imageTarget.value.refs=[...imageSelected.value.values()];closeColorImages()}
function closeColorImages(){imageGeneration++;imageTarget.value=undefined;imageOptions.value=[];imageBusy.value=false}
function removeColorImage(id:number){if(colorEditor.value)colorEditor.value.refs=(colorEditor.value.refs||[]).filter(ref=>ref.id!==id)}
async function uploadColorImage(file:File){if(!canUpload.value)return false;imageBusy.value=true;imageError.value='';try{if(!file.type.startsWith('image/'))throw new Error('颜色色卡只支持图片，请将报价原件保留在来源资料。');if(file.size>MAX_UPLOAD_FILE_SIZE_BYTES)throw new Error(`单个文件不能超过 ${formatFileSize(MAX_UPLOAD_FILE_SIZE_BYTES)}`);const saved=await uploadDocument(file,{fileCategory:'sample_image',versionNo:'V1',references:[],remark:`供应商 ${props.supplierCode} 颜色 ${imageTarget.value?.name||''} 的图片依据`});toggleColorImage(saved,true);await loadColorImages()}catch(e){imageError.value=partnerError(e)}finally{imageBusy.value=false}return false}
</script>
<template><section class="supplier-colors" v-loading="busy"><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="color-toolbar"><el-input v-model="keyword" clearable :aria-label='uiText("搜索供应商颜色")' :placeholder='uiText("搜索颜色名称或供方色号")' @keyup.enter="page=1;load()"/><el-button @click="page=1;load()">{{ uiText("查询") }}</el-button><el-button v-if="canEdit" type="primary" @click="editColor()">{{ uiText("新增颜色") }}</el-button></div><div class="color-list"><article v-for="color in rows" :key="color.id"><div class="color-name"><strong>{{color.name}}</strong><small v-if="color.supplierColorCode">{{ uiText("供方色号：") }}{{color.supplierColorCode}}</small><small v-if="color.status==='inactive'">{{ uiText("已停用") }}</small><details v-if="color.styleKey||color.configKey||color.notes||color.refs.length"><summary>{{ uiText("色卡与补充资料") }}</summary><p v-if="color.styleKey||color.configKey">{{color.styleKey}}<template v-if="color.configKey"> · {{color.configKey}}</template></p><p v-if="color.notes">{{color.notes}}</p><div v-for="ref in color.refs" :key="ref.id" class="color-image-reference"><PartnerPhoto :id="ref.id" previewable/><span>{{ref.name||uiText('颜色色卡')}}</span></div></details></div><div v-if="canEdit" class="color-actions"><el-button link type="primary" :aria-label="uiText('编辑颜色 ')+color.name" @click="editColor(color)">{{ uiText("编辑") }}</el-button><el-button link @click="setStatus(color)">{{color.status==='active'?uiText('停用'):uiText('启用')}}</el-button></div></article><el-empty v-if="!rows.length&&!busy" :description='uiText("暂无通用颜色，可添加常用候选或新增颜色")'/></div><el-pagination v-model:current-page="page" :total="total" :page-size="20" :pager-count="5" layout="total,prev,pager,next" @current-change="load"/><details class="color-more"><summary>{{ uiText("更多") }}</summary><el-button v-if="canEdit&&common.length" :disabled="busy" @click="addCommon">{{ uiText("添加常用颜色") }}</el-button><el-checkbox v-model="includeHistory" @change="page=1;load()">{{ uiText("包含历史款式／色卡专用记录") }}</el-checkbox></details>
 <el-dialog :model-value="!!colorEditor" :title="colorEditor?.id?uiText('编辑供应商颜色'):uiText('新增供应商颜色')" width="min(680px,96vw)" append-to-body :close-on-click-modal="false" @close="colorEditor=undefined"><el-form v-if="colorEditor" label-position="top" size="small"><el-form-item :label='uiText("颜色名称 *")'><el-input v-model="colorEditor.name"/></el-form-item><el-form-item :label='uiText("供方色号（选填）")'><el-input v-model="colorEditor.supplierColorCode" :placeholder='uiText("没有可留空")'/></el-form-item><details><summary>{{ uiText("色卡与更多资料") }}</summary><section class="color-image-section"><header><span>{{ uiText("颜色色卡（选填）") }}</span><el-button link type="primary" @click="chooseColorImages(colorEditor)">{{ uiText("选择图片") }}</el-button></header><div v-for="ref in colorEditor.refs" :key="ref.id" class="color-image-reference"><PartnerPhoto :id="ref.id" previewable/><span>{{ref.name||uiText('颜色色卡')}}</span><el-button link @click="removeColorImage(ref.id)">{{ uiText("移除引用") }}</el-button></div></section><el-form-item :label='uiText("备注")'><el-input v-model="colorEditor.notes" type="textarea" autosize/></el-form-item><el-form-item :label='uiText("适用款式（选填）")'><el-input v-model="colorEditor.styleKey"/></el-form-item><el-form-item :label='uiText("适用配置（选填）")'><el-input v-model="colorEditor.configKey"/></el-form-item><el-form-item :label='uiText("变更说明")'><el-input v-model="reason"/></el-form-item></details></el-form><template #footer><el-button :disabled="busy" @click="colorEditor=undefined">{{ uiText("取消") }}</el-button><el-button type="primary" :disabled="!colorEditor?.name?.trim()||busy" @click="saveColor">{{ uiText("保存颜色") }}</el-button></template></el-dialog>
 <el-dialog :model-value="!!imageTarget" :title='uiText("选择已有色卡图片")' width="min(850px,96vw)" append-to-body @close="closeColorImages"><section v-loading="imageBusy"><el-alert v-if="imageError" :title="imageError" type="error" :closable="false"/><div class="color-toolbar"><el-input v-model="imageKeyword" :aria-label='uiText("搜索色卡图片")' :placeholder='uiText("搜索已有图片")' @keyup.enter="imagePage=1;loadColorImages()"/><el-button @click="imagePage=1;loadColorImages()">{{ uiText("查询") }}</el-button><el-upload v-if="canUpload" :show-file-list="false" :before-upload="uploadColorImage" accept=".png,.jpg,.jpeg,.webp"><el-button :disabled="imageBusy">{{ uiText("上传图片") }}</el-button></el-upload></div><div class="color-image-options"><article v-for="file in imageOptions" :key="file.attachmentId"><PartnerPhoto :id="file.attachmentId" previewable/><el-checkbox :model-value="imageSelected.has(file.attachmentId)" @change="toggleColorImage(file,Boolean($event))">{{file.originalFileName}}</el-checkbox></article></div><el-pagination v-model:current-page="imagePage" :total="imageTotal" :page-size="12" layout="total,prev,pager,next" @current-change="loadColorImages"/></section><template #footer><el-button @click="closeColorImages">{{ uiText("取消") }}</el-button><el-button type="primary" :disabled="imageBusy" @click="applyColorImages">{{ uiText("采用所选图片") }}</el-button></template></el-dialog>
</section></template>
<style scoped>.supplier-colors{min-width:0;container-type:inline-size}.color-toolbar{display:flex;gap:7px;align-items:center;flex-wrap:wrap;margin-bottom:8px}.color-toolbar>.el-input{flex:1;min-width:140px}.color-list{max-height:min(460px,calc(100dvh - 260px));overflow-y:auto}.color-list article{display:flex;justify-content:space-between;gap:12px;align-items:start;padding:8px 0;border-bottom:1px solid var(--el-border-color-lighter);font-size:12px;min-width:0}.color-name{display:flex;flex-direction:column;min-width:0;overflow-wrap:anywhere}.color-name strong{font-weight:500}.color-name small,.supplier-colors p{font-size:12px;color:var(--el-text-color-secondary)}.color-actions{display:flex;gap:8px;flex:none}.supplier-colors :deep(.el-button+.el-button){margin-left:0}.supplier-colors :deep(.el-pagination){flex-wrap:wrap;margin-top:8px}.supplier-colors summary{font-size:12px;color:var(--el-text-color-secondary);cursor:pointer}.color-more{margin-top:9px}.color-more>.el-checkbox{margin-left:10px}.color-image-reference{display:flex;align-items:center;gap:7px;flex-wrap:wrap;font-size:12px;margin:7px 0;min-width:0;overflow-wrap:anywhere}.color-image-section{margin:10px 0}.color-image-section header{display:flex;justify-content:space-between;gap:8px}.color-image-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.color-image-options article{display:flex;gap:7px;align-items:center;min-width:0}.color-image-options :deep(.el-checkbox__label){white-space:normal;overflow-wrap:anywhere;font-size:12px}@container(max-width:500px){.color-image-options{grid-template-columns:minmax(0,1fr)}}</style>
